def _symlink_in_chain(path: Path, stop_at: Path) -> bool:
    cursor = path
    while True:
        try:
            if cursor.is_symlink():
                return True
        except OSError:
            return True
        if cursor == stop_at or cursor.parent == cursor:
            return False
        cursor = cursor.parent


def _refuse_existing_state_dir(path: Path, label: str) -> None:
