    inspect: Mapping[str, Any] | None,
) -> dict[str, Any] | None:
    index_state = None if inspect is None else inspect.get("index_state")
    needs = added or index_state in {None, "missing", "stale"}
    if not needs:
        index_path = workspace / ".light-index" / "index.v1.json"
