KNOWLEDGE_STATE_DIR = ".light-knowledge"
RECORDS_DIRNAME = "records"
STAGING_DIRNAME = "staging"
HEADS_NAME = "HEADS.json"
VIEWS_ROOT = "knowledge"
VIEWS_DIRNAME = "views"
