                document_id = sha256_canonical({"context": context, "document": document})
                target = require_work_output(
                    _default_output(workspace, document_id), code=LIGHT_COMPARISON_INVALID
                )
            else:
                target = require_work_output(output, code=LIGHT_COMPARISON_INVALID)
            return _import_comparison_locked(workspace, context, document, target)

def _publish_json_pointer(workspace: Path, *, kind: str, target_id: str, relative_target: str, payload: dict[str, Any]) -> None:
    destination = workspace / relative_target
    encoded = persisted_bytes(payload)
    if destination.exists() or destination.is_symlink():
        _require_safe_file(destination, relative_target)
        if destination.read_bytes() == encoded:
            return
        existing = _load_persisted_object(destination)
        if existing is None or existing.get("schema") != payload.get("schema"):
            _raise(LIGHT_KNOWLEDGE_CONFLICT, "existing managed pointer is not a validated object")

def _publish_json_pointer(workspace: Path, *, kind: str, target_id: str, relative_target: str, payload: dict[str, Any]) -> None:
