NOTES_NAME = "notes.md"
OWNERSHIP_NAME = "ownership.json"
PAYLOAD_DIRNAME = "payload"
DOCUMENT_NAME = "document.json"
CONTEXT_NAME = "context.json"
IDENTITY_NAME = "identity.json"
MANIFEST_NAME = "manifest.json"
